versions.variantCss:
.wemd-two-column-cards[data-variant="bytedance-tcc-grid"] {
  margin: 16px 0;
}
.wemd-two-column-cards[data-variant="bytedance-tcc-grid"] .wemd-tcc-wrapper {
  display: flex;
  flex-wrap: wrap;
  margin: 0 -6px;
}
.wemd-two-column-cards[data-variant="bytedance-tcc-grid"] .wemd-tcc-item {
  flex: 1;
  min-width: 45%;
  background: var(--wemd-bg-card);
  border-radius: var(--wemd-border-radius);
  padding: 20px;
  margin: 6px;
  border: 1px solid var(--wemd-border-soft);
  box-shadow: var(--wemd-shadow);
  text-align: center;
}
.wemd-two-column-cards[data-variant="bytedance-tcc-grid"] .wemd-tcc-icon {
  font-size: 28px;
  margin: 0 0 8px 0;
}
.wemd-two-column-cards[data-variant="bytedance-tcc-grid"] .wemd-tcc-title {
  color: var(--wemd-primary);
  font-size: 15px;
  font-weight: 700;
  margin: 0 0 6px 0;
}
.wemd-two-column-cards[data-variant="bytedance-tcc-grid"] .wemd-tcc-desc {
  color: var(--wemd-text-soft);
  font-size: 13px;
  line-height: 1.6;
  margin: 0;
}
